parameters.jsCode:
// Configuração do endpoint (linha de endpoints_extracao)
const ep = $('Ler endpoint').first().json;
const caminho = (ep.caminhoRegistros || '').trim();
const obrigatorios = String(ep.camposObrigatorios || '').split(',').map(s => s.trim()).filter(Boolean);
const cargaId = `${ep.entidade}-${$execution.id}`;

// 1. Achatar: cada item é uma página { <caminho>: [...] } ou já um registro (API devolve array na raiz)
const registros = $input.all().flatMap(item => {
  const corpo = item.json;
  if (caminho) return Array.isArray(corpo[caminho]) ? corpo[caminho] : [];
  return Object.keys(corpo).length ? [corpo] : [];
});

// 2. Regras por registro: chave presente e única no lote, obrigatórios preenchidos, data de atualização válida
const vistos = new Set();
const saida = registros.map(r => {
  const erros = [];
  const chave = r[ep.campoId];
  if (chave === undefined || chave === null || chave === '') erros.push(`sem ${ep.campoId}`);
  else if (vistos.has(String(chave))) erros.push('duplicado no lote');
  else vistos.add(String(chave));
  for (const campo of obrigatorios) {
    if (r[campo] === undefined || r[campo] === null || r[campo] === '') erros.push(`sem ${campo}`);
  }
  let atualizado = null;
  if (ep.campoAtualizacao) {
    const dt = r[ep.campoAtualizacao] ? DateTime.fromISO(String(r[ep.campoAtualizacao])) : null;
    if (dt && dt.isValid) atualizado = dt.toUTC().toISO();
    else erros.push(`${ep.campoAtualizacao} inválido`);
  }
  return {
    chaveExterna: String(chave ?? ''),
    atualizadoFonte: atualizado,
    payload_object: JSON.stringify(r),
    dqStatus: erros.length ? 'REJEITADO' : 'OK',
    dqErros: erros.join('; '),
  };
});

// 3. Regra do lote: bloqueia a carga inteira se a taxa de rejeição passar do limite do endpoint
const rejeitados = saida.filter(s => s.dqStatus === 'REJEITADO').length;
const taxa = saida.length ? rejeitados / saida.length : 0;
const limite = (ep.limiteRejeicaoPct ?? 5) / 100;
const status = saida.length === 0 ? 'SEM_NOVOS' : (taxa > limite ? 'BLOQUEADA' : 'APROVADA');
// Novo watermark = maior data de atualização entre os registros aprovados (ISO UTC ordena como texto)
const datasOk = saida.filter(s => s.dqStatus === 'OK' && s.atualizadoFonte).map(s => s.atualizadoFonte).sort();
const novoWatermark = datasOk.length ? datasOk[datasOk.length - 1] : (ep.watermark ?? null);

const lote = {
  cargaId, entidade: ep.entidade, fonteNome: ep.fonteNome, status,
  recebidos: saida.length, rejeitados, aprovados: saida.length - rejeitados,
  taxaRejeicaoPct: Math.round(taxa * 1000) / 10, novoWatermark,
};
if (!saida.length) return [{ json: lote }];
return saida.map(s => ({ json: { ...s, ...lote } }));

