={{ (() => {
  const ep = $('Ler endpoint').first().json
  const dq = $('Normalizar e aplicar DQ')
  if (dq.isExecuted) {
    const lote = dq.first().json
    // Até 5 exemplos de registros rejeitados para diagnóstico
    const exemplos = dq.all().filter(i => i.json.dqStatus === 'REJEITADO').slice(0, 5)
      .map(i => (i.json.chaveExterna || '?') + ': ' + i.json.dqErros).join(' | ')
    if (lote.status === 'SEM_NOVOS') return 'Nenhum registro novo desde o último watermark'
    if (lote.status === 'BLOQUEADA') return 'Rejeição ' + lote.taxaRejeicaoPct + '% acima do limite de ' + (ep.limiteRejeicaoPct ?? 5) + '%. ' + exemplos
    return lote.rejeitados ? lote.rejeitados + ' registro(s) descartado(s): ' + exemplos : 'OK'
  }
  if ($('Extrair registros').isExecuted) return ('Falha na extração: ' + ($json.error?.message || $json.message || JSON.stringify($json))).slice(0, 300)
  if (!ep.id) return 'Endpoint inexistente ou inativo'
  return 'Fonte ' + ep.fonteNome + ' não está ativa/VALIDA (rodar WF10)'
})() }}

